/**
 * Unit tests for ShippingCostCalculator.
 *
 * Covers: weight validation, base price tiers, per-started-kilogram pricing above 20 kg,
 * zone factors and zone case-insensitivity, invalid zones, express surcharge,
 * null express meaning standard delivery, DOMESTIC standard free shipping threshold,
 * and HALF_UP rounding to 2 decimal places.
 */
@isTest
private class ShippingCostCalculatorTest {

    private static Decimal quote(Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        return ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
    }

    /** Compares numerically, normalising both sides to scale 2 so scale differences can't hide bugs. */
    private static void assertPrice(Decimal expected, Decimal actual) {
        System.assertEquals(
            expected.setScale(2, System.RoundingMode.HALF_UP),
            actual.setScale(2, System.RoundingMode.HALF_UP),
            'Unexpected price'
        );
    }

    private static void assertShippingException(Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        Boolean thrown = false;
        try {
            ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        } catch (ShippingCostCalculator.ShippingException e) {
            thrown = true;
        }
        System.assert(thrown, 'Expected ShippingException for weightKg=' + weightKg + ', zone=' + zone);
    }

    // ------------------------------------------------------------------
    // Base price tiers
    // ------------------------------------------------------------------
    @isTest
    static void basePriceTierBoundaries() {
        assertPrice(5.00, quote(0.5, 'DOMESTIC', false, null));
        assertPrice(5.00, quote(1.0, 'DOMESTIC', false, null));   // 1 kg inclusive
        assertPrice(9.50, quote(1.1, 'DOMESTIC', false, null));
        assertPrice(9.50, quote(3.0, 'DOMESTIC', false, null));
        assertPrice(9.50, quote(5.0, 'DOMESTIC', false, null));   // 5 kg inclusive
        assertPrice(18.00, quote(5.1, 'DOMESTIC', false, null));
        assertPrice(18.00, quote(10.0, 'DOMESTIC', false, null));
        assertPrice(18.00, quote(20.0, 'DOMESTIC', false, null)); // 20 kg inclusive
    }

    // ------------------------------------------------------------------
    // Above 20 kg: 18.00 plus 0.75 per started kilogram
    // ------------------------------------------------------------------
    @isTest
    static void overweightChargesPerStartedKilogram() {
        assertPrice(18.75, quote(20.1, 'DOMESTIC', false, null)); // one started kg
        assertPrice(18.75, quote(20.5, 'DOMESTIC', false, null));
        assertPrice(18.75, quote(20.9, 'DOMESTIC', false, null));
        assertPrice(18.75, quote(21.0, 'DOMESTIC', false, null));
        assertPrice(19.50, quote(22.0, 'DOMESTIC', false, null)); // two started kg
        assertPrice(20.25, quote(22.1, 'DOMESTIC', false, null)); // three started kg
        assertPrice(21.00, quote(24.0, 'DOMESTIC', false, null));
    }

    // ------------------------------------------------------------------
    // Zone factors and case-insensitivity
    // ------------------------------------------------------------------
    @isTest
    static void zoneFactorsAndCaseInsensitivity() {
        assertPrice(5.00, quote(1.0, 'DOMESTIC', false, null));
        assertPrice(5.00, quote(1.0, 'domestic', false, null));
        assertPrice(5.00, quote(1.0, 'DoMeStIc', false, null));

        assertPrice(7.00, quote(1.0, 'EU', false, null));
        assertPrice(7.00, quote(1.0, 'eu', false, null));
        assertPrice(7.00, quote(1.0, 'Eu', false, null));

        assertPrice(11.00, quote(1.0, 'WORLD', false, null));
        assertPrice(11.00, quote(1.0, 'world', false, null));
        assertPrice(11.00, quote(1.0, 'WoRlD', false, null));

        assertPrice(25.20, quote(10.0, 'EU', false, null));
        assertPrice(39.60, quote(10.0, 'WORLD', false, null));
    }

    // ------------------------------------------------------------------
    // Invalid weight
    // ------------------------------------------------------------------
    @isTest
    static void invalidWeightThrows() {
