/**
 * Marks Account records as synced to the ERP system.
 *
 * A transaction finalizer is attached before any work is done so that every
 * run is logged in FB_Job_Log__c and failed runs are retried automatically.
 */
public class ErpAccountSyncJob implements Queueable {

    private Set<Id> accountIds;
    private Integer attempt;

    /**
     * @param accountIds Accounts to sync.
     * @param attempt    Attempt number for this run; the first run uses 1.
     */
    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer first, so it runs whether this job succeeds or fails.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accountsToSync = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToSync.add(new Account(
                Id = accountId,
                Description = 'Synced to ERP'
            ));
        }

        if (!accountsToSync.isEmpty()) {
            // All-or-nothing DML: an exception propagates and fails the whole job,
            // so none of the changes are kept.
            update accountsToSync;
        }
    }
}
