/**
 * LogPurgeJob
 *
 * Scheduled maintenance job that purges old FB_Integration_Log__c records so
 * that integration logging does not consume unbounded storage.
 *
 * Retention rules applied on every run:
 *   - Logs whose Level__c is anything other than 'ERROR' (including logs with
 *     a blank/empty Level__c) are deleted once they are more than 30 days old.
 *   - Logs whose Level__c is 'ERROR' are kept until they are more than 180 days
 *     old.
 *
 * The schedulable entry point delegates the actual deletion to a batch job so
 * that arbitrarily large volumes of records can be removed without breaching
 * governor limits.
 */
public with sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    /** Retention window (in days) for non-ERROR logs. */
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;

    /** Retention window (in days) for ERROR logs. */
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Number of records processed per batch chunk. */
    private static final Integer BATCH_SIZE = 2000;

    /** Cron expression: every day at 02:00. */
    private static final String CRON_NIGHTLY = '0 0 2 * * ?';

    /** Name under which the scheduled job is registered. */
    private static final String JOB_NAME = 'Log purge (nightly)';

    /**
     * Explicit no-argument constructor required for System.schedule.
     */
    public LogPurgeJob() {
    }

    /**
     * Schedulable entry point. Kicks off the purge batch each night.
     */
    public void execute(SchedulableContext sc) {
        Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
    }

    /**
     * Batchable start. Selects every log record that has exceeded its
     * applicable retention window.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime nonErrorCutoff = DateTime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE ((Level__c != 'ERROR' OR Level__c = null) AND CreatedDate < :nonErrorCutoff)
               OR (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
        ]);
    }

    /**
     * Batchable execute. Deletes the scoped records, allowing partial success
     * so that a single locked/undeletable record does not abort the purge.
     */
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        if (!scope.isEmpty()) {
            Database.delete(scope, false);
        }
    }

    /**
     * Batchable finish. No post-processing is required.
     */
    public void finish(Database.BatchableContext bc) {
        // Nothing to do.
    }

    /**
     * Schedules the purge to run every day at 02:00 under the job name
     * 'Log purge (nightly)'.
     *
     * @return the Id returned by the scheduling call.
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_NIGHTLY, new LogPurgeJob());
    }
}
