        List<Opportunity> opps = new List<Opportunity>{
            buildOpportunity('Prospecting',    null,   50), // ignored - no Amount
            buildOpportunity('Prospecting',  100.00, null), // ignored - no Probability
            buildOpportunity('Needs Analysis', null,   10), // ignored - stage must not appear
            buildOpportunity('Prospecting',  100.00,   50), // 50.00
