/**
 * Domain class for the Opportunity SObject.
 *
 * Fulfilment is started when an Opportunity is created as 'Closed Won', or when
 * an existing Opportunity transitions to 'Closed Won' from any other stage.
 * Editing an Opportunity that was already 'Closed Won' does not qualify again.
 */
public with sharing class Opportunities extends fflib_SObjectDomain {

    public static final String CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opportunity : (List<Opportunity>) Records) {
            if (opportunity.StageName == CLOSED_WON) {
                qualifyingIds.add(opportunity.Id);
            }
        }
        startFulfilment(qualifyingIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opportunity : (List<Opportunity>) Records) {
            Opportunity existing = (Opportunity) existingRecords.get(opportunity.Id);
            if (opportunity.StageName == CLOSED_WON && existing.StageName != CLOSED_WON) {
                qualifyingIds.add(opportunity.Id);
            }
        }
        startFulfilment(qualifyingIds);
    }

    /**
     * Invokes the fulfilment service exactly once for every qualifying Opportunity
     * in the current trigger invocation, and not at all when none qualify.
     */
    private void startFulfilment(Set<Id> qualifyingIds) {
        if (qualifyingIds == null || qualifyingIds.isEmpty()) {
            return;
        }
        IOpportunityFulfilmentService service =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        service.startFulfilment(qualifyingIds);
    }
}
