/**
 * Pushes new Accounts to the ERP as customers through the Named Credential `ERP`.
 *
 * ERP contract:
 *   POST callout:ERP/api/customers
 *   Content-Type: application/json
 *   Body: JSON array of 1..200 customers
 *         [{"salesforceId": "001...", "name": "Acme GmbH", "country": "Germany"}]
 *   Response: 202 Accepted
 *
 * Finance wants one request per Account, so every request carries an array with
 * exactly one customer.
 *
 * The trigger cannot make the callout itself: the insert DML is still pending in
 * the transaction ("uncommitted work pending"). The trigger therefore hands the
 * work to a Queueable. Because Salesforce allows a maximum of 100 callouts per
 * transaction and a marketplace batch can hold up to 200 Accounts, the job sends
 * up to 100 callouts and chains the rest to a follow-up job.
 */
public with sharing class ErpCustomerSync {

    /** Named Credential supplies the base URL and authentication. */
    private static final String ENDPOINT = 'callout:ERP/api/customers';

    /** Salesforce limit: maximum number of callouts per transaction. */
    private static final Integer MAX_CALLOUTS_PER_TRANSACTION = 100;

    /**
     * Entry point for AccountTrigger (after insert).
     *
     * Keeps the trigger transaction light and bulk-safe: it only collects the
     * new Account Ids and enqueues a single job.
     *
     * @param accounts the newly inserted Accounts (Trigger.new)
     */
    public static void enqueue(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        for (Account acc : accounts) {
            accountIds.add(acc.Id);
        }

        System.enqueueJob(new CustomerSyncJob(new List<Id>(accountIds)));
    }

    /**
     * Sends exactly one Account as a one-element JSON array, per the ERP contract.
     */
    @TestVisible
    private static void sendCustomer(Account acc) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT);
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(new List<CustomerDto>{ new CustomerDto(acc) }));

        HttpResponse res = new Http().send(req);

        if (res.getStatusCode() != 202) {
            throw new CalloutException(
                'ERP did not accept Account ' + acc.Id +
                ': HTTP ' + res.getStatusCode() + ' ' + res.getStatus()
            );
        }
    }

    /**
     * Wire format for a single customer. Field order matches the ERP contract.
     * BillingCountry is sent as null when blank.
     */
    private class CustomerDto {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerDto(Account acc) {
            this.salesforceId = acc.Id; // always the 18-character Id in Apex
            this.name = acc.Name;
            this.country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;
        }
    }

    /**
     * Makes one callout per Account. A single transaction may only contain
     * 100 callouts, so anything beyond that is chained to a follow-up job.
     * (Scope: up to 200 Accounts per batch => at most 2 jobs, well inside the
     * chained-Queueable limit.)
     */
    private class CustomerSyncJob implements Queueable, Database.AllowsCallouts {

        private final List<Id> accountIds;

        private CustomerSyncJob(List<Id> accountIds) {
            this.accountIds = accountIds;
        }

        public void execute(QueueableContext context) {
            Integer total = accountIds.size();
            Integer headSize = Math.min(total, MAX_CALLOUTS_PER_TRANSACTION);

            List<Id> head = new List<Id>();
            List<Id> tail = new List<Id>();
            for (Integer i = 0; i < total; i++) {
                if (i < headSize) {
                    head.add(accountIds[i]);
                } else {
                    tail.add(accountIds[i]);
                }
            }

            for (Account acc : [
                SELECT Id, Name, BillingCountry
                FROM Account
                WHERE Id IN :head
            ]) {
                sendCustomer(acc);
            }

            if (!tail.isEmpty()) {
                System.enqueueJob(new CustomerSyncJob(tail));
            }
        }
    }
}
```

