public with sharing class AccountCountrySync {

    private static final Integer DML_CHUNK_SIZE = 10000;

    public static void syncMailingCountry(List<Account> newAccounts, Map<Id, Account> oldAccountsMap) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccountsMap == null) {
            return;
        }

        Map<Id, Account> newAccountsMap = new Map<Id, Account>(newAccounts);
        Set<Id> changedAccountIds = new Set<Id>();
        Set<String> previousCountries = new Set<String>();

        for (Account newAcc : newAccounts) {
            Account oldAcc = oldAccountsMap.get(newAcc.Id);
            if (oldAcc == null) {
                continue;
            }

            if (countryChanged(newAcc.BillingCountry, oldAcc.BillingCountry)) {
                changedAccountIds.add(newAcc.Id);
                if (!String.isBlank(oldAcc.BillingCountry)) {
                    previousCountries.add(oldAcc.BillingCountry);
                }
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // One selective query. Do not load all contacts in the org.
        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
              AND (MailingCountry = NULL OR MailingCountry IN :previousCountries)
        ];

        for (Contact c : contacts) {
            Account oldAcc = oldAccountsMap.get(c.AccountId);
            Account newAcc = newAccountsMap.get(c.AccountId);

            if (oldAcc == null || newAcc == null) {
                continue;
            }

            String oldCountry = oldAcc.BillingCountry;
            Boolean shouldUpdate = String.isBlank(c.MailingCountry)
                || (!String.isBlank(oldCountry) && oldCountry.equalsIgnoreCase(c.MailingCountry));

            if (shouldUpdate) {
                c.MailingCountry = newAcc.BillingCountry;
                contactsToUpdate.add(c);
            }
        }

        updateContacts(contactsToUpdate);
    }

    private static Boolean countryChanged(String newCountry, String oldCountry) {
        if (String.isBlank(newCountry) && String.isBlank(oldCountry)) {
            return false;
        }
        if (newCountry == null) {
            return oldCountry != null;
        }
        if (oldCountry == null) {
            return true;
        }
        return !newCountry.equals(oldCountry);
    }

    private static void updateContacts(List<Contact> contactsToUpdate) {
        if (contactsToUpdate == null || contactsToUpdate.isEmpty()) {
            return;
        }

        List<Contact> chunk = new List<Contact>();
        for (Contact c : contactsToUpdate) {
            chunk.add(c);
            if (chunk.size() == DML_CHUNK_SIZE) {
                update chunk;
                chunk.clear();
            }
        }
        if (!chunk.isEmpty()) {
            update chunk;
        }
    }
}
```

