import { LightningElement } from 'lwc';

// Module-scoped counter so every instance gets a unique body id, even if the
// component is rendered several times on the same page (e.g. outside of a
// shadow boundary or when IDs are queried from the light DOM).
let instanceCounter = 0;

/**
 * collapsibleSection
 *
 * A reusable WAI-ARIA disclosure (show/hide) component.
 *
 * Usage:
 *   <c-collapsible-section>
 *       <span slot="title">Billing details</span>
 *       <p>Any body content…</p>
 *   </c-collapsible-section>
 *
 * Accessibility notes:
 *  - The trigger is a native <button>, so it is focusable and keyboard
 *    operable (Enter / Space) with no extra key handling required.
 *  - aria-expanded always reflects the current state ("true" / "false").
 *  - aria-controls always points at the id of the .section-body element,
 *    which is always present in the DOM. When collapsed the element carries
 *    the `hidden` attribute, which removes it (and any focusable descendants)
 *    from the accessibility tree and the tab order.
 */
export default class CollapsibleSection extends LightningElement {
    /** The section starts collapsed. */
    isCollapsed = true;

    /** Stable, unique id for the body region referenced by aria-controls. */
    bodyId = `collapsible-section-body-${instanceCounter++}`;

    /** aria-expanded must be a literal string, not a boolean. */
    get ariaExpanded() {
        return this.isCollapsed ? 'false' : 'true';
    }

    handleToggle() {
        this.isCollapsed = !this.isCollapsed;
    }
}
