```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    _debounceTimer;
    _requestId = 0;
    _isActive = false;

    connectedCallback() {
        this._isActive = true;
    }

    disconnectedCallback() {
        // The component is gone: never let a pending search run or resolve.
        this._isActive = false;
        this._clearDebounceTimer();
    }

    handleChange(event) {
        const searchTerm = (event.target.value || '').trim();

        // Any keystroke supersedes whatever was scheduled before.
        this._clearDebounceTimer();

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            // Invalidate in-flight responses and clear the results.
            this._requestId += 1;
            this.contacts = [];
            this.error = undefined;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = undefined;
            this._search(searchTerm);
        }, DEBOUNCE_MS);
    }

    async _search(searchTerm) {
        const requestId = ++this._requestId;

        try {
            const results = await searchContacts({ searchTerm });

            // Ignore stale responses and responses that arrive after unmount.
            if (!this._isActive || requestId !== this._requestId) {
                return;
            }

            this.contacts = results || [];
            this.error = undefined;
        } catch (error) {
            if (!this._isActive || requestId !== this._requestId) {
                return;
            }

            this.contacts = [];
            this.error = this._getErrorMessage(error);
        }
    }

    _clearDebounceTimer() {
        if (this._debounceTimer !== undefined) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = undefined;
        }
    }

    _getErrorMessage(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        if (error && error.message) {
            return error.message;
        }
        return 'Unknown error';
    }
}
