import { LightningElement, wire } from 'lwc';
import {
    APPLICATION_SCOPE,
    MessageContext,
    publish,
    subscribe,
    unsubscribe
} from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    /** Id of the currently selected account, or null when nothing is selected. */
    recordId = null;

    /** The single active subscription, kept so we never hold more than one. */
    subscription = null;

    @wire(MessageContext)
    messageContext;

    connectedCallback() {
        this.subscribeToMessageChannel();
    }

    disconnectedCallback() {
        this.unsubscribeFromMessageChannel();
    }

    /**
     * Subscribe with APPLICATION_SCOPE so this panel receives messages published
     * from the utility bar (a different Lightning page/area of the app).
     * Guarded so a second connectedCallback never creates a duplicate subscription.
     */
    subscribeToMessageChannel() {
        if (this.subscription) {
            return;
        }
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    /**
     * Tear the subscription down completely so the component can be inserted
     * again later (e.g. a reopened tab) and subscribe cleanly.
     */
    unsubscribeFromMessageChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    /** A message with no recordId (or an explicit null) clears the selection. */
    handleMessage(message) {
        this.recordId = (message && message.recordId) ? message.recordId : null;
    }

    /** Broadcast a clear so every listening component resets its selection. */
    handleClear() {
        publish(this.messageContext, ACCOUNT_SELECTED, { recordId: null });
    }

    get hasRecordId() {
        return !!this.recordId;
    }
}
