import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines = [];

    hasError = false;

    handleClick(event) {
        const action = event.target.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        this.template.querySelectorAll('c-line-item-editor').forEach((editor) => {
            editor.reset();
        });
        this.hasError = false;
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');

        // Validate every editor so all invalid lines show their errors at once.
        let allValid = true;
        editors.forEach((editor) => {
            if (!editor.validate()) {
                allValid = false;
            }
        });

        if (!allValid) {
            this.hasError = true;
            return;
        }

        this.hasError = false;

        const lines = Array.from(editors).map((editor) => editor.getValue());

        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines }
            })
        );
    }
}
