import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;

    _pollTimer = null;
    _requestInFlight = false;
    _connected = false;
    _onVisibilityChange = null;

    connectedCallback() {
        this._connected = true;
        this._onVisibilityChange = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._onVisibilityChange);
        this.startPolling();
    }

    disconnectedCallback() {
        // Stop every loop and detach the listener so nothing keeps running
        // or calling Apex after the component leaves the page.
        this._connected = false;
        this.stopPolling();
        if (this._onVisibilityChange) {
            document.removeEventListener('visibilitychange', this._onVisibilityChange);
            this._onVisibilityChange = null;
        }
    }

    get hasStats() {
        return (
            this.waiting !== undefined &&
            this.waiting !== null &&
            this.longestWaitMinutes !== undefined &&
            this.longestWaitMinutes !== null
        );
    }

    get hasError() {
        return this.error !== undefined && this.error !== null;
    }

    get errorMessage() {
        return this.error && this.error.body ? this.error.body.message : undefined;
    }

    get pageIsVisible() {
        return document.visibilityState === 'visible';
    }

    handleVisibilityChange() {
        if (this.pageIsVisible) {
            // Became visible again: load now and resume the 60s cadence.
            this.startPolling();
        } else {
            // Hidden tab: make no requests at all.
            this.stopPolling();
        }
    }

    startPolling() {
        // Guarantee a single polling loop, even if called repeatedly.
        this.stopPolling();
        if (!this._connected || !this.pageIsVisible) {
            return;
        }
        this.loadStats();
        this._pollTimer = setInterval(() => {
            if (this.pageIsVisible) {
                this.loadStats();
            }
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._pollTimer !== null) {
            clearInterval(this._pollTimer);
            this._pollTimer = null;
        }
    }

    async loadStats() {
        // No request while disconnected, while hidden, or while one is in flight.
        if (!this._connected || !this.pageIsVisible || this._requestInFlight) {
            return;
        }
        this._requestInFlight = true;
        try {
            const stats = await getQueueStats();
            if (!this._connected) {
                return;
            }
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.error = undefined;
        } catch (err) {
            if (!this._connected) {
                return;
            }
            this.error = err;
        } finally {
            this._requestInFlight = false;
        }
    }
}
