import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const PERSONAL_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        const value = event.detail.value;

        if (field === 'fullName') {
            this.fullName = value;
        } else if (field === 'email') {
            this.email = value;
        } else if (field === 'company') {
            this.company = value;
        }
    }

    handleRegister() {
        const inputs = Array.from(this.template.querySelectorAll('lightning-input'));
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');

        // Step 1: reject personal email domains before validating anything else.
        const email = (this.email || '').trim();
        const atIndex = email.lastIndexOf('@');
        const domain = atIndex > -1 ? email.slice(atIndex + 1).toLowerCase() : '';

        if (PERSONAL_EMAIL_DOMAINS.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: validate every input so all messages show at once.
        let allValid = true;
        inputs.forEach((input) => {
            if (!input.reportValidity()) {
                allValid = false;
            }
        });

        // Step 3: stop when anything is invalid.
        if (!allValid) {
            return;
        }

        // Step 4: register imperatively and report the outcome.
        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error.body ? error.body.message : error.message
                    })
                );
            });
    }
}
