import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        // Keep the parent's value untouched and work on our own copy.
        this._tasks = value;
        this.items = Array.isArray(value) ? value.map((task) => ({ ...task })) : [];
    }

    get displayHeading() {
        // Display only: never mutate the value the parent set.
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }

        const id = `new-${this.nextId++}`;

        // New array (and a fresh task object) so the template re-renders.
        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';

        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;

        // Replace the task object instead of mutating it, so the getters
        // (`remaining`) and the template see the change.
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
