public class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all GAU allocations on the given Opportunity with one allocation
     * per entry in percentByGauId.
     *
     * Allocations are written with npsp__Percent__c set, which lets the NPSP
     * Allocation trigger keep npsp__Amount__c in sync whenever the Opportunity
     * Amount changes later (e.g. $1,000 split 60/40 -> $1,200 / $800 after the
     * gift is corrected to $2,000).
     *
     * All validation is performed before any data is changed.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ----- Validate input arguments -----
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation percentage is required.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A General Accounting Unit Id is required for every allocation.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null) {
                throw new AllocationException('Allocation percentage cannot be null for GAU ' + gauId + '.');
            }
            if (pct <= 0) {
                throw new AllocationException('Allocation percentage must be greater than 0 for GAU ' + gauId + '.');
            }
            totalPercent += pct;
        }
        if (totalPercent > 100) {
            throw new AllocationException(
                'Allocation percentages total ' + totalPercent + ', which exceeds 100%.'
            );
        }

        // ----- Validate the GAUs -----
        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
            ]
        );
        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit not found: ' + gauId + '.');
            }
            if (!gau.npsp__Active__c) {
                throw new AllocationException('General Accounting Unit is inactive: ' + gauId + '.');
            }
        }

        // ----- Validate the Opportunity -----
        List<Opportunity> opps = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
        ];
        if (opps.isEmpty()) {
            throw new AllocationException('Opportunity not found: ' + opportunityId + '.');
        }
        Decimal oppAmount = opps[0].Amount == null ? 0 : opps[0].Amount;

        // ----- Build the new allocations -----
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            Decimal pct = percentByGauId.get(gauId);
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = pct,
                npsp__Amount__c = oppAmount * pct / 100
            ));
        }

        // ----- Replace the existing allocations -----
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        insert newAllocations;

        return newAllocations;
    }
}
