            .get('HH_Account')
            .getRecordTypeId();

        Account household = new Account(RecordTypeId = householdRecordTypeId);
        insert household;

        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;

        household.npo02__Primary_Contact__c = members[0].Id;
        update household;

        return household.Id;
    }
