        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) oppIds.add(req.opportunityId);
            if (req.contactId != null) contactIds.add(req.contactId);
        }

        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        List<OpportunityContactRole> existingOCRs = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ];
        Map<String, OpportunityContactRole> ocrMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : existingOCRs) {
            String key = ocr.OpportunityId + '|' + ocr.ContactId;
            if (!ocrMap.containsKey(key)) {
                ocrMap.put(key, ocr);
            }
        }

        List<npsp__Partial_Soft_Credit__c> existingPSCs = [
            SELECT Id, npsp__Contact__c, npsp__Opportunity__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Opportunity_Contact_Role__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ];
        Map<String, npsp__Partial_Soft_Credit__c> pscMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : existingPSCs) {
            String key = psc.npsp__Opportunity__c + '|' + psc.npsp__Contact__c;
            if (!pscMap.containsKey(key)) {
                pscMap.put(key, psc);
            }
        }

        // Validate all requests before any DML
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Opportunity Id and Contact Id are required.');
            }
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException('Contact cannot be the primary contact of the opportunity.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive.');
            }
            if (req.amount > opp.Amount) {
                throw new SoftCreditException('Amount cannot exceed the opportunity amount.');
            }
        }

        List<OpportunityContactRole> ocrInserts = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrUpdates = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> ocrToUse = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;
            OpportunityContactRole ocr = ocrMap.get(key);
            if (ocr == null) {
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrInserts.add(ocr);
            } else if (ocr.Role != req.role) {
                ocr.Role = req.role;
                ocrUpdates.add(ocr);
            }
            ocrToUse.put(key, ocr);
        }

        if (!ocrInserts.isEmpty()) {
            insert ocrInserts;
        }
        if (!ocrUpdates.isEmpty()) {
            update ocrUpdates;
        }

        List<npsp__Partial_Soft_Credit__c> pscInserts = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscUpdates = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;
            OpportunityContactRole ocr = ocrToUse.get(key);
            npsp__Partial_Soft_Credit__c psc = pscMap.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Opportunity_Contact_Role__c = ocr.Id
                );
                pscInserts.add(psc);
            } else {
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Opportunity_Contact_Role__c = ocr.Id;
                pscUpdates.add(psc);
            }
        }

        if (!pscInserts.isEmpty()) {
            insert pscInserts;
        }
        if (!pscUpdates.isEmpty()) {
            update pscUpdates;
        }
    }
}
