/**
 * PaymentPlanService
 *
 * Turns an open NPSP donation (pledge) into a monthly installment plan.
 *
 * NPSP creates one unpaid payment for the full opportunity amount whenever a new
 * open donation is created. This service removes the outstanding (unpaid, not
 * written off) payments and replaces them with `numberOfPayments` scheduled
 * unpaid payments whose amounts add up exactly to the outstanding balance.
 *
 * Payments that are already paid or written off are historical and are never
 * touched; their amounts are deducted from the opportunity amount to determine
 * what is still outstanding.
 */
public with sharing class PaymentPlanService {

    /**
     * Thrown when the requested installment plan is invalid or cannot be created.
     * Nothing is changed in the database when this is thrown.
     */
    public class PaymentPlanException extends Exception {}

    /** Scale used for currency amounts (cents). */
    private static final Integer CURRENCY_SCALE = 2;

    /**
     * Replaces the opportunity's outstanding payments with a schedule of
     * `numberOfPayments` unpaid installments.
     *
     * @param opportunityId     Opportunity whose payments should be rescheduled.
     * @param numberOfPayments  Number of installments to create (must be >= 1).
     * @param firstPaymentDate  Date of the first installment; installment i is
     *                          scheduled on firstPaymentDate.addMonths(i).
     * @return The inserted payments, in schedule order.
     * @throws PaymentPlanException if the input is invalid, the opportunity is
     *         closed, or there is no positive outstanding amount.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // ----- Validate input before touching any data -----
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be at least 1.');
        }
        if (opportunityId == null) {
            throw new PaymentPlanException('An opportunity Id is required.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('A first payment date is required.');
        }

        // ----- Lock the opportunity so concurrent changes cannot skew the math -----
        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
            FOR UPDATE
        ];

        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }

        Opportunity opportunity = opportunities[0];

        if (opportunity.IsClosed) {
            throw new PaymentPlanException(
                'Cannot schedule installments on a closed opportunity: ' + opportunityId
            );
        }

        // ----- Lock and inspect the existing payments -----
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            FOR UPDATE
        ];

        Decimal retainedAmount = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : existingPayments) {
            Boolean isPaid = payment.npe01__Paid__c == true;
            Boolean isWrittenOff = payment.npe01__Written_Off__c == true;

            if (isPaid || isWrittenOff) {
                // History: keep it and count it against the opportunity amount.
                retainedAmount += (payment.npe01__Payment_Amount__c == null
                    ? 0
                    : payment.npe01__Payment_Amount__c);
            } else {
                // Outstanding: replace it with the new schedule.
                paymentsToDelete.add(payment);
            }
        }

        Decimal opportunityAmount = (opportunity.Amount == null ? 0 : opportunity.Amount);
        Decimal outstandingAmount = opportunityAmount - retainedAmount;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount must be greater than zero. Opportunity amount: '
                + opportunityAmount + ', already paid/written off: ' + retainedAmount
            );
        }

        // ----- Split the outstanding amount into installments -----
        // Every installment gets the outstanding amount divided by the number of
        // payments, rounded DOWN to the cent. The final installment absorbs the
        // remainder so the installments sum exactly to the outstanding amount.
        Decimal perInstallment = outstandingAmount.divide(
            numberOfPayments,
            CURRENCY_SCALE,
            System.RoundingMode.DOWN
        );
        Decimal finalInstallment = outstandingAmount - (perInstallment * (numberOfPayments - 1));

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            Date scheduledDate = firstPaymentDate.addMonths(i);
            Decimal installmentAmount = (i == numberOfPayments - 1)
                ? finalInstallment
                : perInstallment;

            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = installmentAmount,
                npe01__Payment_Date__c = scheduledDate,
                npe01__Scheduled_Date__c = scheduledDate,
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        // ----- Persist: remove the old outstanding payments, then insert the plan -----
        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }
        insert newPayments;

        // The list preserves schedule order (index i -> firstPaymentDate.addMonths(i)).
        return newPayments;
    }
}
