/**
 * OPP_MajorGiftFollowUp_TDTM
 *
 * NPSP Table-Driven Trigger Management (TDTM) handler for the Opportunity object.
 *
 * Business rule
 * -------------
 * When an Opportunity becomes a major gift - Closed Won with Amount >= 5,000 -
 * either on insert, or on an update that first makes it Closed Won AND >= 5,000,
 * create exactly one follow-up Task for the gift's owner:
 *
 *     Subject      : Major gift thank-you call
 *     Priority     : High
 *     Status       : Not Started
 *     WhatId       : the Opportunity
 *     WhoId        : the Opportunity's npsp__Primary_Contact__c (may be null)
 *     OwnerId      : the Opportunity owner
 *     ActivityDate : CloseDate + 3 days
 *
 * Registration (NPSP Settings > Trigger Configuration > Trigger Handlers)
 * ----------------------------------------------------------------------
 *     Class          : OPP_MajorGiftFollowUp_TDTM
 *     Object         : Opportunity
 *     Trigger Action : AfterInsert;AfterUpdate
 *     Load Order     : 5
 *     Asynchronous   : false
 *
 * Deactivating that Trigger Handler record stops this class from running - there is
 * no Apex trigger in this org, TDTM is the only dispatcher.
 *
 * Design notes
 * ------------
 *  - Bulk safe: the whole trigger batch (e.g. 200 Opportunities) is handled together.
 *  - Governor friendly: exactly one SOQL query and no direct DML of its own. The Task
 *    records are handed back to TDTM via the DmlWrapper, so TDTM performs the single
 *    insert for the entire batch.
 *  - Idempotent: a gift that already qualified, or that already has a follow-up Task
 *    with this subject, never gets a second Task.
 *  - Declared "without sharing" so the dedupe query can see Tasks regardless of the
 *    running user's Task sharing (Tasks default to Private).
 */
global without sharing class OPP_MajorGiftFollowUp_TDTM extends TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;
    private static final String FOLLOW_UP_SUBJECT = 'Major gift thank-you call';
    private static final Integer FOLLOW_UP_OFFSET_DAYS = 3;

    global override TDTM_Runnable.DmlWrapper run(List<SObject> newList,
                                                 List<SObject> oldList,
                                                 TDTM_Runnable.DmlWrapper dmlWrapper,
                                                 Id objResult) {

        // TDTM always passes a wrapper, but never assume it.
        if (dmlWrapper == null) {
            dmlWrapper = new TDTM_Runnable.DmlWrapper();
        }

        // Nothing to do (e.g. an after delete call, or an empty batch).
        if (newList == null || newList.isEmpty()) {
            return dmlWrapper;
        }

        // Old versions of the records. Null/empty on insert.
        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        if (oldList != null) {
            for (SObject oldRecord : oldList) {
                if (oldRecord instanceof Opportunity) {
                    oldOppsById.put(oldRecord.Id, (Opportunity) oldRecord);
                }
            }
        }

        // Opportunities that have *just* become a major gift.
        Map<Id, Opportunity> newlyQualified = new Map<Id, Opportunity>();
        for (SObject record : newList) {
            if (!(record instanceof Opportunity)) {
                continue;
            }
            Opportunity opp = (Opportunity) record;
            if (!isMajorGift(opp)) {
                continue;
            }
            Opportunity oldOpp = oldOppsById.get(opp.Id);
            if (oldOpp != null && isMajorGift(oldOpp)) {
                continue; // it already qualified before - do not create another Task
            }
            newlyQualified.put(opp.Id, opp);
        }

        if (newlyQualified.isEmpty()) {
            return dmlWrapper;
        }

        // One SOQL query for the whole batch: which gifts already have the follow-up Task?
        Set<Id> oppIdsWithFollowUp = new Set<Id>();
        for (Task existingTask : [
                SELECT WhatId
                FROM Task
                WHERE WhatId IN :newlyQualified.keySet()
                AND Subject = :FOLLOW_UP_SUBJECT
        ]) {
            oppIdsWithFollowUp.add(existingTask.WhatId);
        }

        List<SObject> tasksToInsert = new List<SObject>();
        for (Opportunity opp : newlyQualified.values()) {
            if (oppIdsWithFollowUp.contains(opp.Id)) {
                continue; // safety net: never duplicate the follow-up Task
            }
            tasksToInsert.add(buildFollowUpTask(opp));
        }

        // Hand the Tasks to TDTM; it performs the single insert for the batch.
        if (!tasksToInsert.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        }

        return dmlWrapper;
    }

    /**
     * A major gift is a won Opportunity whose Amount is at least 5,000.
     * IsWon is used rather than a hard-coded StageName so the handler keeps
     * working in orgs with custom won stages (and with renamed picklist values).
     */
    private static Boolean isMajorGift(Opportunity opp) {
        return opp != null
            && opp.IsWon
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_AMOUNT;
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        Task followUp = new Task(
            Subject = FOLLOW_UP_SUBJECT,
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId
        );

        if (opp.CloseDate != null) {
            followUp.ActivityDate = opp.CloseDate.addDays(FOLLOW_UP_OFFSET_DAYS);
        }

        return followUp;
    }
}
