/**
 * Returns the subset of record IDs that the running user is allowed to edit,
 * as reported by the UserRecordAccess object (HasEditAccess).
 *
 * UserRecordAccess already factors in everything that matters for a mass-edit
 * screen: object-level CRUD (including Modify All on the object), record
 * ownership, org-wide defaults, sharing rules, manual shares, role hierarchy,
 * and Modify All Data. Records the user cannot even see simply do not come
 * back from the query, so they are excluded automatically.
 *
 * The query is chunked so that a single call can cover up to 2,000 IDs
 * (across any mix of sObjects) without exceeding the per-query row limit
 * for UserRecordAccess and without blowing the transaction's SOQL budget.
 */
public with sharing class RecordAccessService {

    /**
     * UserRecordAccess queries are capped at 200 records, so we check IDs in
     * batches of 200. For the documented 2,000-ID call size this is 10 SOQL
     * queries, comfortably inside the 20-query allowance.
     */
    private static final Integer CHUNK_SIZE = 200;

    /**
     * @param recordIds IDs to check. May span multiple sObjects. May be null or empty.
     * @return the subset of recordIds the running user can edit. Never null.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Flatten to a list so we can slice it into chunks; drop any stray nulls.
        List<Id> pending = new List<Id>();
        for (Id recId : recordIds) {
            if (recId != null) {
                pending.add(recId);
            }
        }

        Integer total = pending.size();
        for (Integer start = 0; start < total; start += CHUNK_SIZE) {
            Integer stop = Math.min(start + CHUNK_SIZE, total);

            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < stop; i++) {
                chunk.add(pending[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
