/**
 * ContactImportService
 *
 * Service class used by the legacy-contact migration. Contacts coming from the
 * legacy system are existing customers, so they must NOT receive the
 * "Send welcome pack" Task created by the after insert trigger action
 * `TA_Contact_CreateWelcomeTask` (Trigger Actions Framework, v0.3.4).
 *
 * All other Contact automation must still run - in particular the before insert
 * action `TA_Contact_FormatPhone`, which strips formatting characters from the
 * Phone field. TAF's bypass API lets us suppress a single registered action
 * while leaving the rest of the framework (and the rest of the org's
 * automation) untouched.
 *
 * The bypass is scoped to this method only: it is cleared in a `finally`
 * block, so once `importContacts` returns (or throws), contacts inserted later
 * in the same transaction get their welcome task as usual.
 */
public with sharing class ContactImportService {
    /**
     * Fully qualified name of the TAF trigger action that must be skipped
     * for legacy contacts. Matches the registered action name on Contact.
     */
    @TestVisible
    private static final String WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    /**
     * Inserts the supplied contacts in a single DML statement with the
     * `TA_Contact_CreateWelcomeTask` trigger action bypassed.
     *
     * @param contacts Contacts to insert. Null or empty input is a no-op.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Enable the bypass just before the DML and keep the returned key so the
        // bypass can be removed precisely - without affecting any other bypass
        // that may already be active in this transaction.
        String bypassKey = TriggerAction.bypass(WELCOME_TASK_ACTION);

        try {
            insert contacts;
        } finally {
            // Always release the bypass, so subsequent inserts in the same
            // transaction (even after a failure) behave normally again.
            TriggerAction.clearBypass(bypassKey);
        }
    }
}
