```apex
/**
 * @description Reassigns books of business between owners.
 *
 *              Account ownership changes must not run any Account trigger actions
 *              (they recalculate territories and are expensive), so the Account
 *              SObject is bypassed in the Trigger Actions Framework (TAF) for the
 *              duration of the change and restored afterwards - whether the DML
 *              succeeds or fails.
 *
 *              Contact trigger actions continue to run normally, and Account
 *              automation is back to normal for the remainder of the transaction
 *              once this method returns or throws.
 *
 *              Bulk-safe: one SOQL query and two all-or-none DML statements,
 *              regardless of how many Accounts are passed in.
 */
public with sharing class AccountOwnershipService {
    private static final String ACCOUNT_SOBJECT_API_NAME = 'Account';

    /**
     * @description Sets OwnerId = newOwnerId on the supplied Accounts and on every
     *              Contact belonging to those Accounts.
     * @param accountIds  The Accounts whose owner (and whose Contacts' owner) changes.
     * @param newOwnerId  The OwnerId to apply.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Query 1: every Contact that belongs to the supplied Accounts.
        List<Contact> contactsToReassign = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
        ];

        List<Account> accountsToReassign = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToReassign.add(new Account(Id = accountId, OwnerId = newOwnerId));
        }
        for (Contact contactRecord : contactsToReassign) {
            contactRecord.OwnerId = newOwnerId;
        }

        // Bypass the whole Account SObject so none of its trigger actions run.
        TriggerActionBypass.bypass(ACCOUNT_SOBJECT_API_NAME);
        try {
            // DML 1: all-or-none. Any exception propagates unchanged to the caller.
            update accountsToReassign;

            // DML 2: all-or-none. Contact trigger actions run normally here.
            update contactsToReassign;
        } finally {
            // Restore Account automation for the rest of the transaction, even if
            // the DML above failed.
            TriggerActionBypass.clearBypass(ACCOUNT_SOBJECT_API_NAME);
        }
    }
}
