/**
 * Unit tests for TA_Opportunity_GuardAmountDecrease.
 *
 * These tests follow the Trigger Actions Framework guidance: no DML and no SOQL.
 * The action's `beforeUpdate` method is invoked directly with in-memory records
 * whose Ids are produced by TAF's TriggerTestUtility.getFakeId(...).
 */
@isTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    private static final Decimal ORIGINAL_AMOUNT = 1000;

    /**
     * Builds an in-memory Opportunity with a fake Id and the given Amount.
     * No DML is performed; the record only exists in memory.
     */
    private static Opportunity buildOpportunity(Id recordId, Decimal amount) {
        return new Opportunity(Id = recordId, Amount = amount);
    }

    /**
     * Runs the action against a single old/new pair and returns the new record.
     */
    private static Opportunity runAction(Opportunity oldOpp, Opportunity newOpp) {
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        return newOpp;
    }

    /**
     * Asserts that a record carries exactly one error with the action's message.
     */
    private static void assertSingleExpectedError(Opportunity opp) {
        System.assert(opp.hasErrors(), 'Expected the record to have an error but it had none.');
        List<Database.Error> errors = opp.getErrors();
        System.assertEquals(1, errors.size(), 'Expected exactly one error on the record, found ' + errors.size() + '.');
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'The error message should match the action constant ERROR_MESSAGE.'
        );
    }

    /**
     * Asserts that a record carries no errors.
     */
    private static void assertNoErrors(Opportunity opp) {
        System.assert(!opp.hasErrors(), 'Expected no errors on the record but found: ' + opp.getErrors());
        System.assertEquals(0, opp.getErrors().size(), 'Expected an empty error list.');
    }

    @isTest
    static void rejectsReductionOfMoreThanHalf() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = buildOpportunity(oppId, ORIGINAL_AMOUNT);
        Opportunity newOpp = buildOpportunity(oppId, 499);

        runAction(oldOpp, newOpp);

        assertSingleExpectedError(newOpp);
    }

    @isTest
    static void acceptsReductionOfExactlyHalf() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = buildOpportunity(oppId, ORIGINAL_AMOUNT);
        Opportunity newOpp = buildOpportunity(oppId, 500);

        runAction(oldOpp, newOpp);

        assertNoErrors(newOpp);
    }

    @isTest
    static void acceptsIncrease() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = buildOpportunity(oppId, ORIGINAL_AMOUNT);
        Opportunity newOpp = buildOpportunity(oppId, 1001);

        runAction(oldOpp, newOpp);

        assertNoErrors(newOpp);
    }

    @isTest
    static void acceptsWhenPreviousAmountIsNull() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = buildOpportunity(oppId, null);
        Opportunity newOpp = buildOpportunity(oppId, 10);

        // Should not throw and should not flag an error.
        runAction(oldOpp, newOpp);

        assertNoErrors(newOpp);
    }

    @isTest
    static void acceptsWhenNewAmountIsNull() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = buildOpportunity(oppId, ORIGINAL_AMOUNT);
        Opportunity newOpp = buildOpportunity(oppId, null);

        runAction(oldOpp, newOpp);

        assertNoErrors(newOpp);
    }

    @isTest
    static void flagsOnlyTheRecordsThatBreakTheRule() {
        Id id1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id3 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id4 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id5 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerOld = new List<Opportunity>{
            buildOpportunity(id1, 1000),   // 1000 -> 499  : breaks the rule
            buildOpportunity(id2, 1000),   // 1000 -> 500  : exactly half, allowed
            buildOpportunity(id3, 1000),   // 1000 -> 2000 : increase, allowed
            buildOpportunity(id4, 800),    // 800  -> 100  : breaks the rule
            buildOpportunity(id5, null)    // null -> 50   : allowed
        };

        List<Opportunity> triggerNew = new List<Opportunity>{
            buildOpportunity(id1, 499),
            buildOpportunity(id2, 500),
            buildOpportunity(id3, 2000),
            buildOpportunity(id4, 100),
            buildOpportunity(id5, 50)
        };

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);

        assertSingleExpectedError(triggerNew[0]);
        assertNoErrors(triggerNew[1]);
        assertNoErrors(triggerNew[2]);
        assertSingleExpectedError(triggerNew[3]);
        assertNoErrors(triggerNew[4]);
    }
}
