/**
 * Trigger Action: TA_Lead_NormalizeContactInfo
 *
 * Runs in the Lead "before insert" context and normalizes contact-related
 * fields directly on the in-memory records (Trigger.new) so that the cleaned
 * values are persisted with the initial insert. No SOQL and no DML are
 * performed, so it is safe for bulk operations (e.g. 200 leads in one insert).
 *
 * - Email     : trimmed and lower-cased (null stays null)
 * - Company   : trimmed
 * - LeadSource: set to 'Web' when blank; existing values are preserved
 */
public with sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.Lead.BeforeInsert {

    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    public void execute(TriggerAction.Context context) {
        List<Lead> newLeads = (List<Lead>) context.newRecords;

        for (Lead lead : newLeads) {
            // Email: trim leading/trailing whitespace and lower-case; null stays null.
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: trim leading/trailing whitespace; null stays null.
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: default to 'Web' when blank; keep any existing value.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = DEFAULT_LEAD_SOURCE;
            }
        }
    }
}
