public without sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> newRecords) {
        List<Case> newCases = (List<Case>) newRecords;
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        updateAccountCounts(accountIds);
    }

    public void afterUpdate(List<SObject> newRecords, List<SObject> oldRecords) {
        List<Case> newCases = (List<Case>) newRecords;
        List<Case> oldCases = (List<Case>) oldRecords;
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < newCases.size(); i++) {
            if (oldCases[i].AccountId != null) {
                accountIds.add(oldCases[i].AccountId);
            }
            if (newCases[i].AccountId != null) {
                accountIds.add(newCases[i].AccountId);
            }
        }
        updateAccountCounts(accountIds);
    }

    public void afterDelete(List<SObject> oldRecords) {
        List<Case> oldCases = (List<Case>) oldRecords;
        Set<Id> accountIds = new Set<Id>();
        for (Case c : oldCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        updateAccountCounts(accountIds);
    }

    public void afterUndelete(List<SObject> newRecords) {
        List<Case> newCases = (List<Case>) newRecords;
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        updateAccountCounts(accountIds);
    }

    private void updateAccountCounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        List<AggregateResult> results = [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE IsClosed = false AND AccountId IN :accountIds
            GROUP BY AccountId
        ];

        Map<Id, Integer> openCounts = new Map<Id, Integer>();
        for (AggregateResult ar : results) {
            openCounts.put((Id) ar.get('AccountId'), (Integer) ar.get('openCount'));
        }

        List<Account> accounts = [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
        ];

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : accounts) {
            Integer newCount = openCounts.containsKey(acc.Id) ? openCounts.get(acc.Id) : 0;
            if (acc.FB_Open_Case_Count__c != newCount) {
                acc.FB_Open_Case_Count__c = newCount;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
