/**
 * TA_Opportunity_LogAmountChange
 *
 * Trigger Action (after update) on Opportunity.
 *
 * Creates exactly one Task per Opportunity whose Amount changed during the
 * transaction, with Subject = 'Amount changed' and Status = 'Completed'.
 *
 * The after-update action TA_Opportunity_RoundAmount (Order__c 20) re-updates the
 * same Opportunities in the same transaction, which re-runs every Opportunity
 * trigger action. That second update is a consequence of the user's change, not a
 * separate change, so this action de-duplicates by Opportunity Id using static
 * state (which lives for the duration of a single transaction). As a result at
 * most one Task is created per Opportunity per transaction.
 *
 * Bulk safe: the Tasks for all Opportunities in the trigger batch are collected
 * and inserted with a single DML statement.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    // Opportunity Ids that have already been logged in this transaction.
    // Static variables are reset between transactions (and between test methods),
    // so this only guards against re-entrant updates inside the same transaction.
    @TestVisible
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpportunity = triggerNew[i];
            Opportunity oldOpportunity = triggerOld[i];

            // Already logged earlier in this transaction (for example by the
            // re-entrant update performed by TA_Opportunity_RoundAmount).
            if (loggedOpportunityIds.contains(newOpportunity.Id)) {
                continue;
            }

            // Amount did not change -> no Task.
            if (newOpportunity.Amount == oldOpportunity.Amount) {
                continue;
            }

            loggedOpportunityIds.add(newOpportunity.Id);

            tasksToInsert.add(new Task(
                Subject = 'Amount changed',
                WhatId = newOpportunity.Id,
                Status = 'Completed'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
